import type { Grammar, Kanji, Listening, Question, QuestionType, Reading, TopicId, Vocabulary } from '../types';

// All examples, texts, dialogues and exercises are original material for this app.
export const advancedScopeNote = 'These original N2 and N1 study groups develop advanced reading, vocabulary, grammar and listening. Labels describe a teaching progression, not an official exhaustive JLPT syllabus. The exercises are original practice and do not reproduce textbooks or historical examination papers.';
export const advancedLevels = [
  {id:'n2',title:'N2 · Understand connections',description:'Work with written arguments, longer explanations, social situations and precise grammar choices.'},
  {id:'n1',title:'N1 · Interpret nuance',description:'Follow complex arguments, implied attitudes, formal expression and decisions with several constraints.'},
] as const;
type AdvancedLevel='n2'|'n1';
type Choice=[text:string,explanation:string];
export const advancedVocabulary:Vocabulary[]=[];
export const advancedGrammar:Grammar[]=[];
export const advancedReadings:Reading[]=[];
export const advancedListening:Listening[]=[];
export const advancedQuestions:Question[]=[];
function question(id:string,skill:Question['skill'],level:AdvancedLevel,topicId:TopicId,questionType:QuestionType,prompt:string,choices:[Choice,Choice,Choice,Choice],links:Partial<Question>={}):string {
  const shift=[...id].reduce((total,c)=>total+c.charCodeAt(0),0)%4;
  const ordered=[...choices.slice(shift),...choices.slice(0,shift)];
  const options=ordered.map(([text],i)=>({id:`${id}-${'abcd'[i]}`,text}));
  advancedQuestions.push({id,skill,jlptLevel:level,topicId,questionType,prompt,options,
    correctOptionId:options[ordered.indexOf(choices[0])].id,
    explanations:Object.fromEntries(ordered.map((choice,i)=>[options[i].id,choice[1]])),...links});
  return id;
}
type Form={before:string;answers:[string,string,string,string];after:string;en:string;wrong:[string,string,string]};
const f=(before:string,answers:Form['answers'],after:string,en:string,wrong:Form['wrong']):Form=>({before,answers,after,en,wrong});
function lesson(level:AdvancedLevel,slug:string,title:string,meaning:string,attachment:string[],category:string,topicId:TopicId,comparison:string,forms:[Form,Form]):void {
  const id=`ag-${level}-${slug}`;
  const examples=forms.map(form=>({ja:form.before+form.answers[0]+form.after,en:form.en}));
  const questionIds=forms.map((form,i)=>question(`qag-${level}-${slug}-${i+1}`,'grammar',level,topicId,'grammar-form',`（　）に入る最もよいものを一つ選んでください。\n${form.before}（　）${form.after}`,
    [[form.answers[0],`${title}: ${meaning} The sentence means: ${form.en}`],...form.wrong.map((reason,j)=>[form.answers[j+1],reason] as Choice)] as [Choice,Choice,Choice,Choice],{grammarId:id}));
  advancedGrammar.push({id,title,meaning,attachment,category,topicId,level:'extension',jlptLevel:level,examples,questionIds,
    mistake:{wrong:forms[0].before+forms[0].answers[1]+forms[0].after,correct:examples[0].ja,explanation:forms[0].wrong[0]},comparison});
}
type SourceSpec={prompt:string;answer:string;evidence:string;reason:string;wrong:[Choice,Choice,Choice]};
const s=(prompt:string,answer:string,evidence:string,reason:string,wrong:[Choice,Choice,Choice]):SourceSpec=>({prompt,answer,evidence,reason,wrong});
function source(kind:'reading'|'listening',level:AdvancedLevel,slug:string,title:string,topicId:TopicId,text:string,translation:string,specs:[SourceSpec,SourceSpec],type:Reading['type']='article',category?:QuestionType):void {
  const id=`a${kind==='reading'?'r':'l'}-${level}-${slug}`;
  const questionIds=specs.map((spec,index)=>{
    if(!text.includes(spec.evidence)) throw new Error(`${id}: evidence must appear literally in its original source.`);
    return question(`q${id}-${index+1}`,kind,level,topicId,category||(kind==='reading'?'reading-medium':index===0?'listening-task':'listening-points'),spec.prompt,
      [[spec.answer,spec.reason],...spec.wrong],{...(kind==='reading'?{passageId:id}:{listeningId:id}),evidence:spec.evidence});
  });
  if(kind==='reading') advancedReadings.push({id,title,type,topicId,jlptLevel:level,body:text,translation,questionIds});
  else advancedListening.push({id,title,topicId,jlptLevel:level,script:text,translation,questionIds});
}

